// version; most production forms set DA at the field level.
type FieldProperties struct{

// Identity.
FullName string ;PartialName string ;AlternateName string ;MappingName string ;Type FieldType ;

// Value.
Value string ;DefaultValue string ;

// Common flags (resolved with inheritance).
ReadOnly bool ;Required bool ;NoExport bool ;

// Text-field flags.
Multiline bool ;Password bool ;FileSelect bool ;DoNotScroll bool ;Comb bool ;RichText bool ;DoNotSpellCheck bool ;

// Choice-field flags.
Combo bool ;Edit bool ;Sort bool ;MultiSelect bool ;CommitOnSelChange bool ;

// Button-field flags.
PushButton bool ;Radio bool ;NoToggleToOff bool ;RadiosInUnison bool ;

// Variable-text properties (parsed from inherited DA).
FontName string ;FontSize float64 ;TextColor PdfColor ;Alignment Quadding ;

// Text-specific.
MaxLength int ;

// Choice-specific.
Options []string ;

// Widget appearance characteristics, taken from /MK on the first widget
// annotation. Nil colors / empty strings when /MK is absent. For
// multi-widget fields callers can use Widgets to inspect each one.
BorderColor PdfColor ;BackgroundColor PdfColor ;Caption string ;Rotation int ;

// Per-widget snapshots for fields with more than one annotation
// (radio groups, multi-page widgets, etc.).
Widgets []WidgetProperties ;};

